<script setup>
import { computed } from 'vue';
import { formatInvoiceCurrency, formatInvoiceDate } from '@/utils/formatters';
const props = defineProps({ invoice: { type: Object, required: true }, company: { type: Object, required: true }, client: Object, paymentAccount: Object, template: { type: Object, required: true } });
const subtotal = computed(() => props.invoice.items?.reduce((sum, item) => sum + Number(item.price || 0) * Number(item.qty || 0), 0) || 0);
const total = computed(() => subtotal.value - Number(props.invoice.discount || 0));
</script>
<template><article class="invoice-document invoice-print relative min-h-[297mm] w-[210mm] shrink-0 overflow-hidden bg-white px-[20mm] py-[16mm] text-[12px] text-[#171717]"><div class="invoice-background absolute inset-0"/><div class="invoice-background invoice-background--bottom absolute inset-0"/><i class="accent top-0 right-0"/><i class="accent accent-mid top-[74px] right-0"/><i class="accent accent-light top-[137px] right-0"/><i class="accent bottom-0 left-0"/><i class="accent accent-mid bottom-[74px] left-0"/><i class="accent accent-light bottom-[137px] left-0"/><div class="relative z-10 flex min-h-[265mm] flex-col"><header class="grid grid-cols-[1fr_1.45fr] items-center gap-6"><img v-if="template.showLogo" :src="company.logoUrl" :alt="company.name" class="h-[46px] max-w-[235px] object-contain object-left"/><div v-if="template.showTagline" class="text-center"><p class="text-[15px] font-bold text-[#444]">{{company.tagline}}</p><p class="mt-0.5 text-[9px] text-[#777]">Website: {{company.website}} | Email: {{company.email}}</p></div></header><section class="mt-14 grid grid-cols-[1fr_auto] gap-8"><div class="space-y-1.5 leading-tight"><p><b class="inline-block w-[112px]">Invoice Name</b>: {{invoice.name}}</p><p v-if="template.showInvoiceDate"><b class="inline-block w-[112px]">Invoice Date</b>: {{formatInvoiceDate(invoice.date)}}</p><p v-if="template.showDueDate"><b class="inline-block w-[112px]">Due Date</b>: {{formatInvoiceDate(invoice.dueDate)}}</p></div><div class="min-w-[210px] text-right"><h1 v-if="template.showTitle" class="text-[16px] font-bold">{{template.title}}</h1><p v-if="template.showNumber" class="mt-1">No. {{invoice.number}}</p></div></section><section class="mt-10 grid grid-cols-2 gap-8"><div v-if="template.showClient"><b>Bill To:</b><p class="mt-1 leading-[1.35]">{{invoice.client}}<br/>{{client?.alamat||'-'}}<br/><span v-if="client?.telepon">Ph: {{client.telepon}}</span><span v-else>{{client?.email}}</span></p></div><div class="pl-2"><b>Total Due:</b><p class="mt-1 text-[13px]">{{formatInvoiceCurrency(total)}}</p></div></section><table v-if="template.showItems" class="mt-12 w-full border-collapse leading-tight"><thead class="bg-[#f4f4f4]"><tr class="border border-[#7b7b7b]"><th class="border-r border-[#7b7b7b] px-2 py-1.5 text-center">Item Description</th><th class="w-[19%] border-r border-[#7b7b7b] px-2 py-1.5 text-center">Price</th><th class="w-[12%] border-r border-[#7b7b7b] px-2 py-1.5 text-center">Qty</th><th class="w-[21%] px-2 py-1.5 text-center">Total</th></tr></thead><tbody><tr v-for="item in invoice.items" :key="item.id" class="border border-t-0 border-[#7b7b7b]"><td class="border-r border-[#7b7b7b] px-2 py-1.5">{{item.description||item.product}}</td><td class="border-r border-[#7b7b7b] px-2 py-1.5 text-right">{{formatInvoiceCurrency(item.price)}}</td><td class="border-r border-[#7b7b7b] px-2 py-1.5 text-center">{{item.qty}}</td><td class="px-2 py-1.5 text-right">{{formatInvoiceCurrency(item.price*item.qty)}}</td></tr></tbody></table><section class="ml-auto mt-2 w-[52%] leading-tight"><div v-if="template.showSubtotal" class="flex justify-between py-1.5"><b>Subtotal</b><span>{{formatInvoiceCurrency(subtotal)}}</span></div><div v-if="template.showDiscount" class="flex justify-between py-1.5"><b>Discount</b><span>{{invoice.discount?formatInvoiceCurrency(invoice.discount):'0'}}</span></div><div v-if="template.showTotal" class="flex justify-between border-t border-[#565656] py-2 text-[13px]"><b>Total Due</b><b>{{formatInvoiceCurrency(total)}}</b></div></section><section class="mt-11 max-w-[74%] leading-[1.35]"><div v-if="template.showBankInfo"><b>Payment Method:</b><p class="mt-2 font-semibold">{{paymentAccount?.nama||'-'}} {{paymentAccount?.nomor||''}}</p><p>{{paymentAccount?.atasNama||company.name}}</p><p v-if="paymentAccount?.cabang">{{paymentAccount.cabang}}</p></div><div v-if="template.showTerms" class="mt-5"><b>Terms &amp; Condition:</b><ul class="mt-2 list-disc space-y-1 pl-5"><li>{{invoice.terms||'Silakan lakukan pembayaran ke rekening yang tertera di atas.'}}</li><li>Mohon konfirmasi pembayaran melalui email balasan pada email tagihan ini.</li></ul></div></section><section v-if="template.showStamp||template.showSignature" class="mt-auto flex justify-end pt-12"><div class="w-[240px] text-center"><p>{{company.signingCity||'Bandung'}}, {{formatInvoiceDate(invoice.date)}}</p><img v-if="template.showSignature&&company.signatureUrl" :src="company.signatureUrl" class="mx-auto my-2 h-9 max-w-40 object-contain"/><div v-else class="h-8"/><div v-if="template.showStamp" class="mx-auto flex h-[60px] w-[225px] items-center justify-center border border-[#444] bg-white/75"><img :src="company.stampUrl||company.logoUrl" class="h-10 max-w-[185px] object-contain grayscale contrast-125"/></div><p v-if="template.showSignerName" class="mt-2 font-bold">{{company.signerName}}</p><p v-if="template.showSignerPosition">{{company.signerPosition}}</p><p>{{company.name}}</p></div></section><footer class="mt-12 flex justify-between text-[10px]"><span>INVOICE<br/>No. {{invoice.number}}</span><span>1</span></footer></div></article></template>
<style scoped>.invoice-document{font-family:'Tamil Sangam MN',Arial,sans-serif}.invoice-background{z-index:0;background:url('/images/invoice/bg-invoice.png') center/100% 100% no-repeat}.invoice-background--bottom{transform:rotate(180deg)}.accent{position:absolute;z-index:1;width:12px;height:74px;background:#626ca8}.accent-mid{height:63px;background:#d9e1f3}.accent-light{height:62px;background:#ebeff8}@media print{@page{size:A4 portrait;margin:0}.invoice-print{height:297mm!important;-webkit-print-color-adjust:exact;print-color-adjust:exact}}</style>
